  test("business day terms scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "clerk-limit", "1.50");
    await ui.setSetting(pg_uma, "floor", "2.00");
    await ui.setSetting(pg_uma, "terms", "7");
    await ui.setSetting(pg_uma, "late-pct", "5.00");
    await ui.setSetting(pg_uma, "terms-A", "20");
    await ui.setSetting(pg_uma, "proof-threshold", "3.00");
    expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
    expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50", "from": "2026-03-10"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
    await ui.setToday(pg_uma, "2026-04-09");
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.delegate(pg_wes, {"user": "vic", "from": "2026-03-01", "to": "2026-04-02"})).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    const c_ben_0 = ui.must(await ui.addClaim(pg_vic, p_ben, {"amount": "10.25", "note": "n"}));
    const c_cam_0 = ui.must(await ui.quickAdd(pg_vic, {"name": "Cam", "amount": "99.95"}));
    const c_cam_1 = ui.must(await ui.addClaim(pg_vic, p_cam, {"amount": "0.04", "date": "2026-03-20", "note": "n"}));
    const c_ada_0 = ui.must(await ui.quickAdd(pg_vic, {"name": "Ada", "amount": "10.25"}));
    await ui.refresh(pg_vic);
    expect(await ui.watch(pg_vic, p_ada, true)).toBe(true);
    expect(await ui.editPerson(pg_vic, p_ada, {"grade": "B"})).toBe(true);
    expect(await ui.statementAsOf(pg_vic, p_cam, "2026-03-20")).toBe(true);
    expect(await ui.editPerson(pg_vic, p_ada, {"grade": "A"})).toBe(true);
    const c_ada_1 = ui.must(await ui.addClaimTwice(pg_vic, p_ada, {"amount": "0.40", "date": "2026-04-02"}));
    expect(await ui.claimCount(pg_vic, p_ada)).toBe(2);
    expect(await ui.setRate(pg_vic, {"grade": "C", "pct": "10.00"})).toBe(true);
    await ui.refresh(pg_wes);
    expect(await ui.reassign(pg_wes, c_ben_0, "Ada")).toBe(true);
    await ui.refresh(pg_wes);
    expect(await ui.bulkGrade(pg_wes, [p_ada, p_ben], {"grade": "A", "from": "2026-03-01"})).toBe(2);
    expect(await ui.claimAction(pg_wes, c_ada_0, "open")).toBe(true);
    expect(await ui.setRate(pg_wes, {"grade": "B", "pct": "10.00"})).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.claimAction(pg_vic, c_ada_0, "settle")).toBe(true);
    expect(await ui.claimAction(pg_vic, c_cam_1, "open")).toBe(true);
    await ui.refresh(pg_vic);
    ]);
  });
