    }

    /** Keep the claim as it stands now in its history, with the sheet's today. */
    private void kept(String sheetId, long id) {
        jdbc.update("INSERT INTO claim_history (sheet_id, claim_id, person_id, amount, claim_date, note, status, "
                + "claim_number, settled_due, opened_by, stated, stated_due, corrects, due_by, deferred_until, proofs, "
                + "split_from, late_entry, reminded_on, made_on) SELECT c.sheet_id, c.id, c.person_id, c.amount, c.claim_date, c.note, "
                + "c.status, c.claim_number, c.settled_due, c.opened_by, c.stated, c.stated_due, c.corrects, c.due_by, "
                + "c.deferred_until, c.proofs, c.split_from, c.late_entry, c.reminded_on, s.today FROM claim c JOIN sheet s ON s.id = "
                + "c.sheet_id WHERE c.sheet_id = ? AND c.id = ?", sheetId, id);
    }

    /** Keep the claim in its history when the change went through; whether it did. */
    private boolean kept(Claim claim, boolean changed) {
        if (changed) {
            kept(claim.sheetId(), claim.id());
        }
        return changed;
    }

    /** The sheet's claims as they stood at the end of the day: each claim's last kept state made while the sheet's
     *  today was on or before it (one kept before history was, at any day), newest first; a claim added after then is
     *  not among them. */
    public List<Claim> listAsOf(String sheetId, LocalDate end) {
        return jdbc.query("SELECT h.claim_id AS id, h.* FROM claim_history h WHERE h.sheet_id = ? AND h.id = ("
                + "SELECT MAX(l.id) FROM claim_history l WHERE l.sheet_id = h.sheet_id AND l.claim_id = h.claim_id "
                + "AND (l.made_on IS NULL OR l.made_on <= ?)) ORDER BY h.claim_id DESC", ROW, sheetId, end);
    }

    /** The person's claims as they stood at the end of the day: each claim's last kept state made while the sheet's
     *  today was on or before it (one kept before history was, at any day), newest first; a claim added after then,
     *  or that was another person's then, is not among them. */
    public List<Claim> listForPersonAsOf(String sheetId, long personId, LocalDate end) {
        return jdbc.query("SELECT h.claim_id AS id, h.* FROM claim_history h WHERE h.sheet_id = ? AND h.id = ("
                + "SELECT MAX(l.id) FROM claim_history l WHERE l.sheet_id = h.sheet_id AND l.claim_id = h.claim_id "
                + "AND (l.made_on IS NULL OR l.made_on <= ?)) AND h.person_id = ? ORDER BY h.claim_id DESC",
                ROW, sheetId, end, personId);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A person's claim: an amount (two decimals; below 0.00 only for a correction), a date, a note (may be empty), its
 *  status, its number (sheet-wide digits, or <period name>-<n> / X-<n> when numbered within its period; null while a draft; a voided claim keeps the one it had) and, once settled, the due fixed
 *  at settling (null before then, or when the person's grade had no rate then: its due stays live), and
 *  who opened it (null while a draft), whether its person's last statement bound it (it counted then) and the
 *  figure it bound it to (null when not bound, or its figure was n/a then: its due stays live), and for a correction
 *  (a negative amount) the number of the SETTLED claim of the same person it corrects (null otherwise), and its
 *  due-by, fixed when it was created: its date plus the terms of its person's grade in force on its date (else the
 *  sheet's terms); it does not change when the terms or its date change later; and the date it is deferred until (null: never
 *  deferred): an OPEN claim deferred past the sheet's today is deferred (see deferredOn); and its proofs count (0 or more,
 *  raised one at a time); and the number of the claim it was split from (null when it was not split off one); and whether it is a
 *  late entry: added while its period was soft-closed (fixed when it was added); and the last sheet-today a reminder was
 *  written for it (null: never reminded). */
public record Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, String number, BigDecimal settledDue, String openedBy, boolean stated,
        BigDecimal statedDue, String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs,
        String splitFrom, boolean lateEntry, LocalDate reminded) {

    /** Whether the claim is deferred on the sheet's today: it is OPEN and deferred until a date after today (null:
     *  no today, nothing is deferred). Deferred, it counts in no total, is not overdue, cannot be settled and is
     *  left unbound by a statement; from that date on it is an OPEN claim like any other. */
    public boolean deferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && deferredUntil.isAfter(today);
    }
}
